msg.headers = {
    Authorization: "Bearer " + env.get("IOE_INTERNAL_TOKEN"),
    "Content-Type": "application/json"
};
msg.requestTimeout = 45000;
const gateway = env.get("IOE_GATEWAY_URL") || "http://127.0.0.1:8080";

msg.input = {...msg.payload};
msg.input.request_id = msg.input.request_id || msg._msgid;
msg.input.conversation_id = msg.input.conversation_id || "node-red-demo";
msg.payload = msg.input;
msg.url = gateway + "/internal/interpret";
return msg;

if (msg.statusCode !== 200) {
    const detail = typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload);
    throw new Error("Gateway HTTP " + msg.statusCode + ": " + detail.slice(0, 400));
}

msg.decision = msg.payload;
return msg.decision.kind === "command" ? [msg, null] : [null, msg];

